  1	import java.util.Objects;
  2	import java.util.StringJoiner;
  3	
  4	final class BuildHeap {
  5	    private BuildHeap() {
  6	    }
  7	
  8	    private static void siftDown(int[] values, int heapSize, int startIndex) {
  9	        int currentIndex = startIndex;
 10	
 11	        while (hasLeftChild(currentIndex, heapSize)) {
 12	            int largerChildIndex = largerChildIndex(values, heapSize, currentIndex);
 13	
 14	            if (isHeapOrdered(values, currentIndex, largerChildIndex)) {
 15	                return;
 16	            }
 17	
 18	            swap(values, currentIndex, largerChildIndex);
 19	            currentIndex = largerChildIndex;
 20	        }
 21	    }
 22	
 23	    private static boolean hasLeftChild(int index, int heapSize) {
 24	        return leftChildIndex(index) < heapSize;
 25	    }
 26	
 27	    private static int largerChildIndex(int[] values, int heapSize, int parentIndex) {
 28	        int leftChildIndex = leftChildIndex(parentIndex);
 29	        int rightChildIndex = rightChildIndex(parentIndex);
 30	
 31	        if (isRightChildLarger(values, heapSize, leftChildIndex, rightChildIndex)) {
 32	            return rightChildIndex;
 33	        }
 34	
 35	        return leftChildIndex;
 36	    }
 37	
 38	    private static boolean isHeapOrdered(int[] values, int parentIndex, int childIndex) {
 39	        return values[parentIndex] >= values[childIndex];
 40	    }
 41	
 42	    private static boolean isRightChildLarger(
 43	            int[] values,
 44	            int heapSize,
 45	            int leftChildIndex,
 46	            int rightChildIndex) {
 47	        return rightChildIndex < heapSize && values[rightChildIndex] > values[leftChildIndex];
 48	    }
 49	
 50	    private static int leftChildIndex(int index) {
 51	        return 2 * index + 1;
 52	    }
 53	
 54	    private static int rightChildIndex(int index) {
 55	        return 2 * index + 2;
 56	    }
 57	
 58	    private static void swap(int[] values, int firstIndex, int secondIndex) {
 59	        int temp = values[firstIndex];
 60	        values[firstIndex] = values[secondIndex];
 61	        values[secondIndex] = temp;
 62	    }
 63	
 64	    static void buildHeap(int[] values) {
 65	        buildMaxHeap(values);
 66	    }
 67	
 68	    static void buildMaxHeap(int[] values) {
 69	        Objects.requireNonNull(values, "values");
 70	
 71	        for (int index = lastParentIndex(values.length); index >= 0; index--) {
 72	            siftDown(values, values.length, index);
 73	        }
 74	    }
 75	
 76	    private static int lastParentIndex(int heapSize) {
 77	        return heapSize / 2 - 1;
 78	    }
 79	
 80	    private static String formatValues(int[] values) {
 81	        StringJoiner output = new StringJoiner(" ");
 82	
 83	        for (int value : values) {
 84	            output.add(Integer.toString(value));
 85	        }
 86	
 87	        return output.toString() + " ";
 88	    }
 89	
 90	    private static int[] sampleValues() {
 91	        return new int[] {1, 3, 5, 4, 6, 13, 10, 9, 8, 15, 17};
 92	    }
 93	
 94	    public static void main(String[] args) {
 95	        int[] values = sampleValues();
 96	
 97	        buildMaxHeap(values);
 98	        System.out.println(formatValues(values));
 99	    }
